def get_subjects():
    return list(SUBJECT_QUESTIONS.keys())


def get_questions(subject):
    return SUBJECT_QUESTIONS.get(subject, [])


def get_question_count(subject):
    return len(get_questions(subject))


def calculate_result(subject, answers):
    questions = get_questions(subject)
    correct = 0
    details = []

    for index, question in enumerate(questions):
        text, options, correct_index, explanation, difficulty = question
        selected_index = answers.get(index)
        is_correct = selected_index == correct_index

        if is_correct:
            correct += 1

        details.append({
            "number": index + 1,
            "question": text,
            "options": options,
            "selected_index": selected_index,
            "correct_index": correct_index,
            "is_correct": is_correct,
            "explanation": explanation,
            "difficulty": difficulty,
        })

    total = len(questions)
    percentage = round((correct / total) * 100) if total else 0

    if percentage >= 90:
        level = "Excellent"
        message = "Outstanding performance. Your fundamentals are very strong."
    elif percentage >= 75:
        level = "Very Good"
        message = "Strong performance. Review the few concepts you missed."
    elif percentage >= 60:
        level = "Good"
        message = "Good foundation. A little targeted revision will help."
    elif percentage >= 40:
        level = "Needs Practice"
        message = "Revise the weaker areas and try the quiz again."
    else:
        level = "Foundation Building"
        message = "Focus on the basics first, then retake the quiz."

    return {
        "subject": subject,
        "correct": correct,
        "total": total,
        "percentage": percentage,
        "level": level,
        "message": message,
        "details": details,
    }
